function calculatePrice(product: any) {
  if (product.type === 'standard') return product.basePrice;
  if (product.type === 'luxury') return product.basePrice * 1.2 + 50;
  if (product.type === 'discount') return product.basePrice * 0.8;
  return product.basePrice;
}

class OrderProcessor {
  process(order: any) {
    switch (order.kind) {
      case 'online': return this.handleOnline(order);
      case 'instore': return this.handleInStore(order);
      case 'wholesale': return this.handleWholesale(order);
    }
  }
}

